INSERT INTO "Recipes" ("Id", "Name", "Description", "Category", "PreparationTime", "Difficulty", "Ingredients", "Instructions", "ImageUrl") VALUES (2, 'עוגת שוקולד עסיסית', 'עוגת שוקולד רכה ועשירה שמתאימה לכל אירוע.', 'קינוחים', 50, 'קל', ARRAY['2 כוסות קמח','1 כוס סוכר','3 ביצים','חצי כוס שמן','1 כוס מים','חצי כוס קקאו','1 שקית אבקת אפייה']::text[], 'מחממים תנור ל-180 מעלות. מערבבים את החומרים היבשים, מוסיפים ביצים, שמן ומים ומערבבים לבלילה אחידה. יוצקים לתבנית משומנת ואופים כ-35 דקות.', 'https://images.unsplash.com/photo-1578985545062-69928b1d9587?w=800') ON CONFLICT ("Id") DO NOTHING;
INSERT INTO "Recipes" ("Id", "Name", "Description", "Category", "PreparationTime", "Difficulty", "Ingredients", "Instructions", "ImageUrl") VALUES (3, 'סלט יווני', 'סלט ירקות רענן עם גבינה וזיתים.', 'סלטים', 15, 'קל', ARRAY['3 עגבניות','2 מלפפונים','1 פלפל אדום','100 גרם גבינה בולגרית','חופן זיתים','2 כפות שמן זית','מיץ לימון']::text[], 'חותכים את הירקות לקוביות. מוסיפים זיתים וגבינה מפוררת. מתבלים בשמן זית ומיץ לימון ומגישים מיד.', 'https://images.unsplash.com/photo-1512621776951-a57141f2eefd?w=800') ON CONFLICT ("Id") DO NOTHING;
INSERT INTO "Recipes" ("Id", "Name", "Description", "Category", "PreparationTime", "Difficulty", "Ingredients", "Instructions", "ImageUrl") VALUES (4, 'פסטה ברוטב עגבניות', 'פסטה ביתית ברוטב עגבניות ובזיליקום.', 'מנות עיקריות', 30, 'קל', ARRAY['500 גרם פסטה','4 עגבניות','2 שיני שום','2 כפות שמן זית','כף רסק עגבניות','מלח','פלפל','בזיליקום']::text[], 'מבשלים את הפסטה לפי ההוראות. מטגנים שום בשמן זית, מוסיפים עגבניות קצוצות ורסק ומבשלים 15 דקות. מתבלים ומערבבים עם הפסטה.', 'https://images.unsplash.com/photo-1473093295043-cdd812d0e601?w=800') ON CONFLICT ("Id") DO NOTHING;
INSERT INTO "Recipes" ("Id", "Name", "Description", "Category", "PreparationTime", "Difficulty", "Ingredients", "Instructions", "ImageUrl") VALUES (5, 'עוגיות שוקולד צ''יפס', 'עוגיות פריכות מבחוץ ורכות מבפנים.', 'קינוחים', 30, 'קל', ARRAY['2 כוסות קמח','100 גרם חמאה','חצי כוס סוכר','1 ביצה','כפית תמצית וניל','כוס שוקולד צ''יפס','חצי כפית אבקת אפייה']::text[], 'מחממים תנור ל-175 מעלות. מערבבים חמאה וסוכר, מוסיפים ביצה ווניל, ואז קמח ואבקת אפייה. מוסיפים שוקולד צ''יפס, יוצרים כדורים ואופים 12 דקות.', 'https://images.unsplash.com/photo-1499636136210-6f4ee915583e?w=800') ON CONFLICT ("Id") DO NOTHING;
INSERT INTO "Recipes" ("Id", "Name", "Description", "Category", "PreparationTime", "Difficulty", "Ingredients", "Instructions", "ImageUrl") VALUES (6, 'שניצל עוף פריך', 'שניצל זהוב ופריך שמתאים לארוחת צהריים.', 'מנות עיקריות', 35, 'קל', ARRAY['500 גרם חזה עוף','2 ביצים','כוס פירורי לחם','חצי כוס קמח','מלח','פלפל','שמן לטיגון']::text[], 'מתבלים את העוף. מצפים כל נתח בקמח, בביצה טרופה ובפירורי לחם. מטגנים בשמן חם משני הצדדים עד להזהבה ולבישול מלא של העוף.', 'https://images.unsplash.com/photo-1562967914-608f82629710?w=800') ON CONFLICT ("Id") DO NOTHING;
INSERT INTO "Recipes" ("Id", "Name", "Description", "Category", "PreparationTime", "Difficulty", "Ingredients", "Instructions", "ImageUrl") VALUES (7, 'סלט כרוב וגזר', 'סלט פריך עם רוטב לימוני קליל.', 'סלטים', 15, 'קל', ARRAY['חצי כרוב לבן','2 גזרים','2 כפות שמן זית','מיץ מחצי לימון','כפית סוכר','מלח','פלפל']::text[], 'פורסים את הכרוב דק ומגררים את הגזר. מערבבים בקערה עם שמן זית, לימון, סוכר, מלח ופלפל. מניחים לעשר דקות לפני ההגשה.', 'https://images.unsplash.com/photo-1540420773420-3366772f4999?w=800') ON CONFLICT ("Id") DO NOTHING;
INSERT INTO "Recipes" ("Id", "Name", "Description", "Category", "PreparationTime", "Difficulty", "Ingredients", "Instructions", "ImageUrl") VALUES (8, 'פנקייקים אווריריים', 'פנקייקים רכים לארוחת בוקר מפנקת.', 'קינוחים', 25, 'קל', ARRAY['כוס וחצי קמח','כוס חלב','1 ביצה','2 כפות סוכר','2 כפיות אבקת אפייה','2 כפות שמן','קורט מלח']::text[], 'מערבבים את כל החומרים לבלילה אחידה. מחממים מחבת משומנת קלות ויוצקים עיגולי בלילה. הופכים כשמופיעות בועות ומטגנים עד להזהבה.', 'https://images.unsplash.com/photo-1528207776546-365bb710ee93?w=800') ON CONFLICT ("Id") DO NOTHING;
INSERT INTO "Recipes" ("Id", "Name", "Description", "Category", "PreparationTime", "Difficulty", "Ingredients", "Instructions", "ImageUrl") VALUES (9, 'אורז עם ירקות', 'אורז צבעוני עם גזר, אפונה ותירס.', 'מנות עיקריות', 40, 'קל', ARRAY['2 כוסות אורז','1 גזר','חצי כוס אפונה','חצי כוס תירס','3 כוסות מים','2 כפות שמן','מלח','כורכום']::text[], 'מטגנים קלות את הגזר הקצוץ והאורז. מוסיפים אפונה, תירס, מים ותבלינים. מביאים לרתיחה, מכסים ומבשלים על אש נמוכה כ-20 דקות.', 'https://images.unsplash.com/photo-1512058564366-18510be2db19?w=800') ON CONFLICT ("Id") DO NOTHING;
INSERT INTO "Recipes" ("Id", "Name", "Description", "Category", "PreparationTime", "Difficulty", "Ingredients", "Instructions", "ImageUrl") VALUES (11, 'מרק ירקות עשיר', 'מרק ביתי חם עם ירקות שורש.', 'מנות עיקריות', 55, 'קל', ARRAY['2 גזרים','2 תפוחי אדמה','1 קישוא','1 בצל','2 גבעולי סלרי','6 כוסות מים','מלח','פלפל','כורכום']::text[], 'קוצצים את כל הירקות. מטגנים בצל, מוסיפים את שאר הירקות, מים ותבלינים. מבשלים כ-40 דקות עד שהירקות מתרככים.', 'https://images.unsplash.com/photo-1547592180-85f173990554?w=800') ON CONFLICT ("Id") DO NOTHING;
INSERT INTO "Recipes" ("Id", "Name", "Description", "Category", "PreparationTime", "Difficulty", "Ingredients", "Instructions", "ImageUrl") VALUES (12, 'בראוניז שוקולד', 'בראוניז עשירים עם מרכז רך ושוקולדי.', 'קינוחים', 40, 'בינוני', ARRAY['200 גרם שוקולד מריר','150 גרם חמאה','3 ביצים','כוס סוכר','חצי כוס קמח','2 כפות קקאו','קורט מלח']::text[], 'ממיסים שוקולד וחמאה. טורפים ביצים וסוכר, מאחדים את התערובות ומוסיפים קמח, קקאו ומלח. יוצקים לתבנית ואופים ב-175 מעלות כ-25 דקות.', 'https://images.unsplash.com/photo-1606313564200-e75d5e30476c?w=800') ON CONFLICT ("Id") DO NOTHING;
INSERT INTO "Recipes" ("Id", "Name", "Description", "Category", "PreparationTime", "Difficulty", "Ingredients", "Instructions", "ImageUrl") VALUES (13, 'פשטידת תפוחי אדמה', 'פשטידה זהובה עם תפוחי אדמה ובצל.', 'מנות עיקריות', 60, 'בינוני', ARRAY['5 תפוחי אדמה','2 בצלים','3 ביצים','3 כפות קמח','3 כפות שמן','מלח','פלפל']::text[], 'מגררים תפוחי אדמה ובצל וסוחטים מעט נוזלים. מוסיפים ביצים, קמח ותבלינים. מעבירים לתבנית משומנת ואופים ב-180 מעלות כ-45 דקות.', 'https://images.unsplash.com/photo-1512621776951-a57141f2eefd?w=800') ON CONFLICT ("Id") DO NOTHING;
INSERT INTO "Recipes" ("Id", "Name", "Description", "Category", "PreparationTime", "Difficulty", "Ingredients", "Instructions", "ImageUrl") VALUES (15, 'מאפינס וניל', 'מאפינס וניל רכים ואווריריים.', 'קינוחים', 35, 'קל', ARRAY['2 כוסות קמח','חצי כוס סוכר','2 ביצים','חצי כוס שמן','כוס חלב','כפית תמצית וניל','2 כפיות אבקת אפייה']::text[], 'מחממים תנור ל-180 מעלות. מערבבים את החומרים הרטובים והיבשים בנפרד ומאחדים בעדינות. ממלאים תבניות מאפינס עד שני שלישים ואופים כ-20 דקות.', 'https://images.unsplash.com/photo-1484723091739-30a097e8f929?w=800') ON CONFLICT ("Id") DO NOTHING;
INSERT INTO "Recipes" ("Id", "Name", "Description", "Category", "PreparationTime", "Difficulty", "Ingredients", "Instructions", "ImageUrl") VALUES (16, 'פיצה ביתית', 'פיצה עם בצק רך, רוטב עגבניות וגבינה.', 'מנות עיקריות', 90, 'בינוני', ARRAY['3 כוסות קמח','כף שמרים יבשים','כפית סוכר','כפית מלח','כוס מים פושרים','2 כפות שמן זית','חצי כוס רוטב עגבניות','200 גרם גבינה צהובה']::text[], 'לשים קמח, שמרים, סוכר, מלח, מים ושמן לבצק. מתפיחים כשעה. מרדדים, מורחים רוטב, מפזרים גבינה ואופים בתנור שחומם ל-220 מעלות עד להזהבה.', 'https://images.unsplash.com/photo-1513104890138-7c749659a591?w=800') ON CONFLICT ("Id") DO NOTHING;
INSERT INTO "Recipes" ("Id", "Name", "Description", "Category", "PreparationTime", "Difficulty", "Ingredients", "Instructions", "ImageUrl") VALUES (10, 'סלט קינואה', 'סלט קינואה צבעוני עם ירקות ועשבי תיבול.', 'סלטים', 30, 'קל', ARRAY['כוס קינואה','2 כוסות מים','1 מלפפון','1 עגבנייה','חופן פטרוזיליה','2 כפות שמן זית','מיץ לימון','מלח']::text[], 'שוטפים את הקינואה ומבשלים במים כ-15 דקות. מצננים, מוסיפים ירקות קצוצים ופטרוזיליה ומתבלים בשמן זית, לימון ומלח.', 'https://images.unsplash.com/photo-1512621776951-a57141f2eefd?w=800') ON CONFLICT ("Id") DO NOTHING;
INSERT INTO "Recipes" ("Id", "Name", "Description", "Category", "PreparationTime", "Difficulty", "Ingredients", "Instructions", "ImageUrl") VALUES (14, 'סלט עגבניות שרי', 'סלט עגבניות שרי עם בזיליקום ושמן זית.', 'סלטים', 10, 'קל', ARRAY['300 גרם עגבניות שרי','חופן עלי בזיליקום','2 כפות שמן זית','כף מיץ לימון','מלח','פלפל']::text[], 'חוצים את עגבניות השרי, מוסיפים עלי בזיליקום ומתבלים בשמן זית, לימון, מלח ופלפל. מערבבים ומגישים.', 'https://images.unsplash.com/photo-1592924357228-91a4daadcfea?w=800') ON CONFLICT ("Id") DO NOTHING;
INSERT INTO "Recipes" ("Id", "Name", "Description", "Category", "PreparationTime", "Difficulty", "Ingredients", "Instructions", "ImageUrl") VALUES (17, 'חול קינטי', 'טעים הכי שיכול להיות ', 'סלטים', 10, 'קל', ARRAY['מים','מלח']::text[], 'אפרת דוידוביץ,אלישבע,מיכל,טלי
